/*
 * Screens on the map: a box's thumbnail, and in the side panel the whole screenshot with each
 * region outlined, numbered and linked to the box that explains it. The images and each
 * region's bounds are generated by `pnpm capture` (`docs/screens/`), so a thumbnail is a CSS
 * crop of the full screen: no image per box.
 */
(() => {
  const ArchMap = globalThis.ArchMap ?? {};
  globalThis.ArchMap = ArchMap;
  const h = globalThis.React.createElement;
  const { useState } = globalThis.React;

  const IMAGES = "../../docs/screens/";
  /** The most a card's thumbnail takes: the card's inner width, and a height that keeps cards short. */
  const THUMB = { width: 194, height: 110 };

  const imageOf = (shot) => `url("${IMAGES}${shot.image}")`;
  const nameOf = (shot, region) => (region ? `${shot.title}: ${region.label}` : shot.title);

  /** The screenshot, or the region of it a box shows, small enough for a card. */
  function Thumb({ shotRef }) {
    const found = ArchMap.model.resolveShot(globalThis.MERIDIAN_SCREENS, shotRef);
    if (found.error) return null;
    const { shot, region } = found;
    const crop = region ?? { x: 0, y: 0, w: shot.width, h: shot.height };
    const scale = Math.min(THUMB.width / crop.w, THUMB.height / crop.h);
    return h("div", {
      className: "thumb",
      role: "img",
      "aria-label": nameOf(shot, region),
      style: {
        width: Math.round(crop.w * scale),
        height: Math.round(crop.h * scale),
        backgroundImage: imageOf(shot),
        backgroundSize: `${shot.width * scale}px ${shot.height * scale}px`,
        backgroundPosition: `${-crop.x * scale}px ${-crop.y * scale}px`,
      },
    });
  }

  /**
   * The full screenshot a box shows, each region outlined and numbered; the list under it says
   * what each is and where its code is. A region is a link to its box; `own` marks the one this
   * box shows, if it shows a region.
   */
  function ShotView({ data, shotRef, onGo }) {
    const { model, SourceLink } = ArchMap;
    const [hot, setHot] = useState(null);
    const found = model.resolveShot(globalThis.MERIDIAN_SCREENS, shotRef);
    if (found.error) return null;
    const { shot, region: own } = found;
    const follow = (ref) => (event) => {
      // A modified click keeps its meaning (a new tab); a plain one stays on the page.
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.button) return;
      event.preventDefault();
      onGo(ref);
    };
    const linkTo = (region) => `#${region.map}`;
    return h(
      "section",
      { className: "panel-section shot" },
      h("h3", null, `Screen: ${shot.title}`),
      h(
        "div",
        { className: "shot-frame", style: { aspectRatio: `${shot.width} / ${shot.height}` } },
        h("img", {
          className: "shot-image",
          src: IMAGES + shot.image,
          alt: `${shot.title}, ${shot.width} by ${shot.height} pixels`,
          width: shot.width,
          height: shot.height,
        }),
        ...shot.regions.map((region, i) =>
          h(
            "a",
            {
              key: region.arch,
              href: linkTo(region),
              onClick: follow(region.map),
              onMouseEnter: () => setHot(region.arch),
              onMouseLeave: () => setHot(null),
              className: `shot-region${region === own || region.arch === own?.arch ? " is-own" : ""}${hot === region.arch ? " is-hot" : ""}`,
              title: `${region.label} → ${region.map}`,
              style: {
                left: `${(region.x / shot.width) * 100}%`,
                top: `${(region.y / shot.height) * 100}%`,
                width: `${(region.w / shot.width) * 100}%`,
                height: `${(region.h / shot.height) * 100}%`,
              },
            },
            h("span", { className: "shot-number" }, i + 1),
          ),
        ),
      ),
      shot.viewer === "placeholder" && shot.regions.some((r) => r.arch === "viewer-panes")
        ? h(
            "p",
            { className: "panel-hint" },
            "The four panes are a placeholder: this picture does not draw the scan.",
          )
        : null,
      h(
        "ol",
        { className: "shot-regions" },
        ...shot.regions.map((region, i) =>
          h(
            "li",
            {
              key: region.arch,
              className: hot === region.arch ? "is-hot" : "",
              onMouseEnter: () => setHot(region.arch),
              onMouseLeave: () => setHot(null),
            },
            h("span", { className: "shot-number" }, i + 1),
            h(
              "span",
              { className: "shot-region-text" },
              h("a", { href: linkTo(region), onClick: follow(region.map) }, region.label),
              h(SourceLink, { data, path: region.code }),
            ),
          ),
        ),
      ),
    );
  }

  ArchMap.Thumb = Thumb;
  ArchMap.ShotView = ShotView;
})();
